package com.dormrepair.config; import org.springframework.boot.context.properties.ConfigurationProperties; import java.time.Duration; import java.util.Set;
@ConfigurationProperties(prefix="app.file-upload") public record FileUploadProperties(long imageMaxSize,long videoMaxSize,Set<String> imageExtensions,Set<String> videoExtensions,Set<String> imageMimeTypes,Set<String> videoMimeTypes,Duration orphanRetention,int cleanupBatchSize){public FileUploadProperties{if(imageMaxSize<=0)imageMaxSize=10*1024*1024L;if(videoMaxSize<=0)videoMaxSize=200*1024*1024L;if(orphanRetention==null)orphanRetention=Duration.ofHours(24);if(cleanupBatchSize<=0)cleanupBatchSize=100;}}
